const language = 'English';
const niches = [
  { niche: 'Clinic', pain: 'patients miss appointments (no-shows) and the front desk answers the same WhatsApp questions all day' },
  { niche: 'Gym', pain: 'new leads are not followed up fast, and membership renewals are forgotten' },
  { niche: 'Hotel', pain: 'booking inquiries arrive after hours and go unanswered, and guests are not asked for reviews' },
  { niche: 'Real estate', pain: 'agents reply to new leads too slowly and site visits are scheduled by hand' },
  { niche: 'Small business', pain: 'owners repeat the same customer replies and track orders or inquiries manually' }
];
return niches.map(n => ({ json: { ...n, language } }));

const out = [];
const niches = $('Niches').all();
const week = new Date().toISOString().slice(0, 10);
$input.all().forEach((item, i) => {
  const raw = item.json.candidates[0].content.parts[0].text;
  let data;
  try {
    data = JSON.parse(raw.replace(/```json|```/g, '').trim());
  } catch (e) {
    return; // skip a niche if Gemini returned bad JSON
  }
  (data.ideas || []).forEach(idea => {
    out.push({ json: {
      week,
      niche: niches[i].json.niche,
      hook: idea.hook,
      script: idea.script,
      demo_to_record: idea.demo_to_record,
      cta: idea.cta,
      status: 'new'
    }});
  });
});
return out;
